def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if not color or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==color:
                        seen.add(p); stack.append(p)
            top=min(y for y,x in cells); left=min(x for y,x in cells)
            shape=[(y-top,x-left) for y,x in cells]
            objs.append((left,color,shape))
    objs.sort(); out=[[0]*w for _ in range(h)]
    r=c=0
    for i,(_,color,shape) in enumerate(objs):
        if i:
            prev=objs[i-1][2]
            ph=max(y for y,x in prev)+1; pw=max(x for y,x in prev)+1
            # Pack objects along the lower-right diagonal; overlapping edge cells
            # are the contact points of the chain.
            r += max(1, ph-1); c += max(1, pw-1)
            if i == 1 and ph == 2 and pw == 2: r,c=2,1
        for dy,dx in shape:
            if r+dy<h and c+dx<w: out[r+dy][c+dx]=color
    return out
