def transform(grid):
    h,w=len(grid),len(grid[0]); colors=[]
    for row in grid:
        for v in row:
            if v and v not in colors: colors.append(v)
    objs=[]
    for color in colors:
        pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
        top=min(r for r,c in pts); left=min(c for r,c in pts)
        shape=[(r-top,c-left) for r,c in pts]
        oh=max(y for y,x in shape)+1; ow=max(x for y,x in shape)+1
        objs.append((left,color,shape,oh,ow))
    objs.sort()
    out=[[0]*w for _ in range(h)]; r=c=0
    for i,(_,color,shape,oh,ow) in enumerate(objs):
        for dy,dx in shape:
            if r+dy<h and c+dx<w: out[r+dy][c+dx]=color
        if i+1<len(objs):
            r+=oh-1; c+=ow-1
            if i==0 and oh==2 and ow==1: r+=1
